const input = $input.first().json.body || $input.first().json;

const token = input.token || ('#TAJ-' + Math.floor(100 + Math.random() * 900));
const customerName = input.customerName || 'Customer';
const phone = input.phone || '';
const items = input.items || [];
const totalAmount = input.totalAmount || '₹0';
const paymentMethod = input.paymentMethod || 'UPI (tajhotelmadurai@upi)';
const specialInstructions = input.specialInstructions || 'None';

let itemsList = '';
if (Array.isArray(items) && items.length > 0) {
  itemsList = items.map(it => `• ${it.quantity || 1}x ${it.itemName || it.name || 'Biryani'}`).join('\n');
} else {
  itemsList = '• 1x Special Biryani Parcel';
}

// WhatsApp Confirmation to Customer
const customerConfirmation = `✅ *ஆர்டர் உறுதியானது! - மதுரை தாஜ் ஹோட்டல்* 🍗\n\n` +
  `வணக்கம் ${customerName}!\n` +
  `🎟️ *உங்கள் டோக்கன் எண்:* *${token}*\n\n` +
  `📋 *ஆர்டர் செய்த பொருட்கள்:*\n${itemsList}\n\n` +
  `💰 *மொத்த பில் தொகை:* ${totalAmount}\n` +
  `💳 *பணம் செலுத்தும் முறை:* ${paymentMethod}\n\n` +
  `⏰ *பார்சல் 10 நிமிடங்களில் தயார்!*\n` +
  `⚡ *கவுண்டரில் வரிசையில் நிற்க வேண்டாம்!* நேராக VIP Pre-Order கவுண்டருக்கு வந்து Token *${token}* சொல்லி உடனே பெற்றுக்கொள்ளலாம்! நன்றி, மீண்டும் வருக! 🙏`;

// Kitchen Display Ticket
const kitchenTicket = `🔔 *KITCHEN DISPLAY TICKET* [TOKEN: ${token}]\n` +
  `👤 Customer: ${customerName} (${phone})\n` +
  `🥘 Items:\n${itemsList}\n` +
  `📝 Notes: ${specialInstructions}\n` +
  `💵 Total: ${totalAmount} (${paymentMethod})\n` +
  `⏱️ Target: 10 mins`;

return [{
  json: {
    token,
    customerName,
    phone,
    totalAmount,
    customerConfirmation,
    kitchenTicket,
    timestamp: new Date().toISOString()
  }
}];
